test-case.test:
(: FTNot-q1: Unadorned ftnot; may get FTST0002 :)
declare variable $input-context external;
$input-context/books/book[para contains text ftnot "ninja"]/title

(: FTNot-q2: Simple ftand ftnot :)
declare variable $input-context external;
$input-context/books/book[para contains text "software" ftand ftnot "ninja"]/title

(: FTAnd-q3: more complex ftnot, may get FTST0002 :)
declare variable $input-context external;
$input-context/books/book[para contains text "software" ftand (ftnot "hacker" ftor "ninja")]/title

(: FTNot-q4: more complex ftnot :)
declare variable $input-context external;
$input-context/books/book[para contains text "software" ftand ftnot ("coder" ftand "ninja")]/title
